// Starting positions for ocean/pokemon9 (2026-10-30): Gen 9 random battles generated by Showdown itself (its own
// random-team generator, seeded), converted to poke-engine state strings at turn 1, after both leads have switched
// in, so lead abilities (Intimidate, Drought, ...) are already applied as in a real game. One state per line.
// Usage (box): NODE_PATH=build/pokemon/showdown_server/node_modules node ocean/pokemon9/build_positions.js N OUT SHARD
const {Battle, Teams} = require('pokemon-showdown');
const fs = require('fs');
const {stateString, skipReasons} = require('./showdown_convert.js');
const [N, OUT, SHARD] = [+process.argv[2] || 1000, process.argv[3] || 'positions.txt', +process.argv[4] || 0];
const out = fs.openSync(OUT, 'w');
let written = 0, game = 0;
while (written < N) {
    game++;
    const teams = [1, 2].map(k => Teams.pack(Teams.getGenerator('gen9randombattle', [game, k, 91, 97 + SHARD]).getTeam()));
    const b = new Battle({formatid: 'gen9randombattle', seed: [game, 5, 7, 11 + SHARD]});
    b.setPlayer('p1', {name: 'a', team: teams[0]});
    b.setPlayer('p2', {name: 'b', team: teams[1]});
    if (b.turn !== 1 || b.ended) continue;
    const s = stateString(b);
    if (!s) continue;
    fs.writeSync(out, s + '\n');
    written++;
}
console.log(JSON.stringify({written, games: game, skipped: skipReasons}));
